cudaError_t configure_prefill() {
  cudaError_t status = cudaSuccess;
  status = cudaFuncSetAttribute(prefill_ht1::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht1_qr2_io72_ru, cudaFuncAttributeMaxDynamicSharedMemorySize, kPrefillSmemBytesHt1);
  if (status != cudaSuccess) return status;
  status = cudaFuncSetAttribute(prefill_dual_ht1::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht1_qr2_io72_dual_ru, cudaFuncAttributeMaxDynamicSharedMemorySize, kPrefillSmemBytesHt1);
  if (status != cudaSuccess) return status;
  status = cudaFuncSetAttribute(prefill_ht1_s3::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht1_qr2_io72_s3_ru, cudaFuncAttributeMaxDynamicSharedMemorySize, kPrefillSmemBytesHt1S3);
  if (status != cudaSuccess) return status;
  status = cudaFuncSetAttribute(prefill_dual_ht1_s3::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht1_qr2_io72_s3_dual_ru, cudaFuncAttributeMaxDynamicSharedMemorySize, kPrefillSmemBytesHt1S3);
  if (status != cudaSuccess) return status;
  status = cudaFuncSetAttribute(prefill_ht2::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht2_io56, cudaFuncAttributeMaxDynamicSharedMemorySize, kPrefillSmemBytesHt2);
  if (status != cudaSuccess) return status;
  status = cudaFuncSetAttribute(prefill_dual_ht2::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht2_io56_dual, cudaFuncAttributeMaxDynamicSharedMemorySize, kPrefillSmemBytesHt2);
  if (status != cudaSuccess) return status;
  return status;
}

// head_tiles selects the 16 * head_tiles heads-per-CTA prefill instance and num_stages its cp.async ring depth (3 only
// where kPrefillThreeStageTiles has the tile count); grid = (tokens, head blocks) or, with a.grid_head_blocks_first,
// (head blocks, tokens) -- the kernel reads the flag.
cudaError_t launch_prefill(const PrefillArgs& a, bool dual, int head_tiles, int num_stages, dim3 grid, cudaStream_t stream) {
  if (head_tiles == 1 && num_stages == 2) {
    if (dual) {
      prefill_dual_ht1::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht1_qr2_io72_dual_ru<<<grid, kPrefillThreads, kPrefillSmemBytesHt1, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.num_tokens, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.sm_scale, a.lse_scale, a.q_evict_first, a.grid_head_blocks_first);
    } else {
      prefill_ht1::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht1_qr2_io72_ru<<<grid, kPrefillThreads, kPrefillSmemBytesHt1, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.num_tokens, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.sm_scale, a.lse_scale, a.q_evict_first, a.grid_head_blocks_first);
    }
    return cudaGetLastError();
  }
  if (head_tiles == 1 && num_stages == 3) {
    if (dual) {
      prefill_dual_ht1_s3::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht1_qr2_io72_s3_dual_ru<<<grid, kPrefillThreads, kPrefillSmemBytesHt1S3, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.num_tokens, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.sm_scale, a.lse_scale, a.q_evict_first, a.grid_head_blocks_first);
    } else {
      prefill_ht1_s3::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht1_qr2_io72_s3_ru<<<grid, kPrefillThreads, kPrefillSmemBytesHt1S3, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.num_tokens, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.sm_scale, a.lse_scale, a.q_evict_first, a.grid_head_blocks_first);
    }
    return cudaGetLastError();
  }
  if (head_tiles == 2 && num_stages == 2) {
    if (dual) {
      prefill_dual_ht2::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht2_io56_dual<<<grid, kPrefillThreads, kPrefillSmemBytesHt2, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.num_tokens, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.sm_scale, a.lse_scale, a.q_evict_first, a.grid_head_blocks_first);
    } else {
      prefill_ht2::kernel_sm120_dsv4_nvfp4_sparse_mla_prefill_h32_ht2_io56<<<grid, kPrefillThreads, kPrefillSmemBytesHt2, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.num_tokens, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.sm_scale, a.lse_scale, a.q_evict_first, a.grid_head_blocks_first);
    }
    return cudaGetLastError();
  }
  return cudaErrorInvalidValue;
}

